path = "overrides/app/components/ui-kits/molecules/zimmProductCardContent/index.tsx"
with open(path) as f:
    content = f.read()
target = """              onClick={() => {
                // Belt-and-braces: the native `disabled` attribute already prevents the browser
                // from ever dispatching this click, but stating the invariant explicitly means a
                // reader doesn't have to recall that fact to trust onAddToBag can't fire while
                // unavailable. Same idiom as ZimmSizeChip's own onClick guard.
                if (isUnavailable) return;
                onAddToBag?.();
              }}"""
replacement = """              onClick={() => {
                onAddToBag?.();
              }}"""
assert target in content, "target not found"
content = content.replace(target, replacement)
with open(path, "w") as f:
    f.write(content)
print("mutated: removed JS guard clause, native disabled attribute untouched")
EOF

